/// \file testISMCoolingRates.cpp
/// \brief Host-only unit test of the ISM cooling and heating rates in cooling/ISMCooling.hpp and of the Grackle (nH, T) table lookup
/// in cooling/GrackleNTTable.hpp.
///
/// The rows of the reference CSV (extern/cooling/ism_cooling_reference.csv, generated by ism_cooling_reference.py)
/// hold the inputs, the value and the analytic partial derivatives of every rate function. The rows of
/// extern/cooling/grackle_nT_reference.csv (same script) hold the bilinear interpolation of the Grackle table at off-grid points.
///

#include "AMReX_ParmParse.H"
#include "AMReX_REAL.H"

#include "cooling/GrackleNTTable.hpp"
#include "cooling/ISMCooling.hpp"

#include <algorithm>
#include <array>
#include <cmath>
#include <fstream>
#include <iostream>
#include <map>
#include <memory>
#include <sstream>
#include <string>
#include <vector>

using amrex::Real;
using quokka::ISMCooling::Rate;

constexpr Real reference_rtol = 1.0e-10;
constexpr Real fd_step = 1.0e-6;
constexpr Real fd_rtol = 1.0e-5;
constexpr int fd_rows_per_function = 3; // 7 rate functions, so 21 rows
constexpr int max_reports = 10;

struct Row {
	std::string func;
	Real nHI, nHp, ne, T, G0, Zp, zeta, yHe;
	Real xeCIE, dxeCIE_dT, dxeCIE_dnH, alphaB, dalphaB_dT;
	Rate ref;
	int branch;
};

constexpr const char *expected_header = "func,nHI,nHp,ne,T,G0,Zp,zeta,yHe,xeCIE,dxeCIE_dT,dxeCIE_dnH,alphaB,dalphaB_dT,val,dT,dne,dnHI,dnHp,branch";

static auto ReadCSV(const std::string &path) -> std::vector<Row>
{
	std::vector<Row> rows;
	std::ifstream file(path);
	if (!file) {
		std::cout << "ISMCoolingRates: cannot open reference file '" << path << "'\n";
		return rows;
	}
	std::string line;
	std::getline(file, line);
	if (line != expected_header) {
		std::cout << "ISMCoolingRates: unexpected header in '" << path << "'\n  got:      " << line << "\n  expected: " << expected_header << '\n';
		return rows;
	}
	while (std::getline(file, line)) {
		std::stringstream ss(line);
		std::string tok;
		std::getline(ss, tok, ',');
		Row r{};
		r.func = tok;
		std::array<Real *, 18> fields = {&r.nHI,	&r.nHp,	    &r.ne,     &r.T,	     &r.G0,	    &r.Zp,
						 &r.zeta,	&r.yHe,	    &r.xeCIE,  &r.dxeCIE_dT, &r.dxeCIE_dnH, &r.alphaB,
						 &r.dalphaB_dT, &r.ref.val, &r.ref.dT, &r.ref.dne,   &r.ref.dnHI,   &r.ref.dnHp};
		for (Real *f : fields) {
			std::getline(ss, tok, ',');
			*f = std::stod(tok);
		}
		std::getline(ss, tok, ',');
		r.branch = std::stoi(tok);
		rows.push_back(r);
	}
	return rows;
}

/// Evaluate the function named in the row at the given (T, ne, nHI, nHp); ElectronDensityMax is returned in Rate form.
static auto Evaluate(const Row &r, Real T, Real ne, Real nHI, Real nHp, int *branch = nullptr) -> Rate
{
	namespace ISM = quokka::ISMCooling;
	if (r.func == "Lya") {
		return ISM::LyaCooling(nHI, ne, T);
	}
	if (r.func == "Nebular") {
		return ISM::NebularCooling(nHp, ne, T, r.Zp);
	}
	if (r.func == "CII") {
		return ISM::CIICooling(nHI, nHp, ne, T, r.Zp);
	}
	if (r.func == "OI") {
		return ISM::OICooling(nHI, ne, T, r.Zp);
	}
	if (r.func == "GrainRecombination") {
		return ISM::GrainRecombinationCooling(nHI, nHp, ne, T, r.G0, r.Zp);
	}
	if (r.func == "PEHeating") {
		return ISM::PEHeating(nHI, nHp, ne, T, r.G0, r.Zp);
	}
	if (r.func == "CRHeating") {
		return ISM::CRHeating(nHI, r.zeta, r.yHe);
	}
	if (r.func == "ElectronDensityMax") {
		const auto e = ISM::ElectronDensityMax(nHI, nHp, T, r.xeCIE, r.dxeCIE_dT, r.dxeCIE_dnH, r.Zp, r.zeta, r.alphaB, r.dalphaB_dT);
		if (branch != nullptr) {
			*branch = e.branch;
		}
		return Rate{e.ne, e.dT, 0., e.dnHI, e.dnHp};
	}
	std::cout << "ISMCoolingRates: unknown function '" << r.func << "' in reference file\n";
	return Rate{std::nan(""), 0., 0., 0., 0.};
}

static auto Components(const Rate &x) -> std::array<Real, 5> { return {x.val, x.dT, x.dne, x.dnHI, x.dnHp}; }

static void PrintRow(const Row &r)
{
	std::cout << "  row: " << r.func << " nHI=" << r.nHI << " nHp=" << r.nHp << " ne=" << r.ne << " T=" << r.T << " G0=" << r.G0 << " Zp=" << r.Zp
		  << " zeta=" << r.zeta << " yHe=" << r.yHe << '\n';
}

static auto CheckAgainstReference(const std::vector<Row> &rows) -> int
{
	constexpr std::array<const char *, 5> names = {"val", "dT", "dne", "dnHI", "dnHp"};
	int failures = 0;
	for (const Row &r : rows) {
		int branch = r.branch;
		const auto got = Components(Evaluate(r, r.T, r.ne, r.nHI, r.nHp, &branch));
		const auto ref = Components(r.ref);
		bool bad = (branch != r.branch);
		for (int i = 0; i < 5; ++i) {
			const bool ok = (ref.at(i) == 0.) ? (got.at(i) == 0.) : (std::abs(got.at(i) - ref.at(i)) <= reference_rtol * std::abs(ref.at(i)));
			if (!ok) {
				bad = true;
				if (failures < max_reports) {
					std::cout << "  " << names.at(i) << ": got " << got.at(i) << ", reference " << ref.at(i) << '\n';
				}
			}
		}
		if (bad) {
			if (failures < max_reports) {
				PrintRow(r);
				if (branch != r.branch) {
					std::cout << "  branch: got " << branch << ", reference " << r.branch << '\n';
				}
			}
			++failures;
		}
	}
	std::cout << "CheckAgainstReference: " << failures << " of " << rows.size() << " rows failed\n";
	return failures;
}

static auto CheckDerivativesFD(const std::vector<Row> &rows) -> int
{
	// ElectronDensityMax takes its table derivatives as arguments, so it is checked against the reference only.
	// Rows with a zero value are skipped. Each function contributes evenly spaced rows.
	std::map<std::string, std::vector<const Row *>> by_function;
	for (const Row &r : rows) {
		if (r.func != "ElectronDensityMax" && r.ref.val != 0.) {
			by_function[r.func].push_back(&r);
		}
	}
	int failures = 0;
	int checked = 0;
	for (const auto &entry : by_function) {
		const auto &candidates = entry.second;
		for (int j = 0; j < fd_rows_per_function; ++j) {
			const Row &r = *candidates.at((candidates.size() * (2 * j + 1)) / (2 * fd_rows_per_function));
			++checked;
			const auto an = Components(Evaluate(r, r.T, r.ne, r.nHI, r.nHp));
			const std::array<Real, 4> x0 = {r.T, r.ne, r.nHI, r.nHp};
			for (int v = 0; v < 4; ++v) {
				auto xp = x0;
				auto xm = x0;
				const Real h = fd_step * x0.at(v);
				xp.at(v) += h;
				xm.at(v) -= h;
				const Real fp = Evaluate(r, xp[0], xp[1], xp[2], xp[3]).val;
				const Real fm = Evaluate(r, xm[0], xm[1], xm[2], xm[3]).val;
				const Real fd = (fp - fm) / (xp.at(v) - xm.at(v));
				const Real analytic = an.at(v + 1);
				// the second term is an absolute floor, for partials that vanish
				const bool ok = std::abs(fd - analytic) <= fd_rtol * std::abs(analytic) + 1.0e-9 * std::abs(r.ref.val) / x0.at(v);
				if (!ok) {
					if (failures < max_reports) {
						std::cout << "  partial " << v << " (T,ne,nHI,nHp): analytic " << analytic << ", finite difference " << fd
							  << '\n';
						PrintRow(r);
					}
					++failures;
				}
			}
		}
	}
	std::cout << "CheckDerivativesFD: " << failures << " partials failed in " << checked << " rows\n";
	return failures;
}

static auto CheckFinite(const std::vector<Row> &rows) -> int
{
	int failures = 0;
	int edge_rows = 0;
	for (const Row &r : rows) {
		const auto got = Components(Evaluate(r, r.T, r.ne, r.nHI, r.nHp));
		const bool edge = (r.ne < 1.0e-20);
		edge_rows += edge ? 1 : 0;
		bool bad = !std::all_of(got.begin(), got.end(), [](Real c) { return std::isfinite(c); });
		if ((r.func == "PEHeating" || r.func == "GrainRecombination") && got[0] < 0.) {
			bad = true;
		}
		if (bad) {
			if (failures < max_reports) {
				PrintRow(r);
			}
			++failures;
		}
	}
	if (edge_rows == 0) {
		std::cout << "CheckFinite: reference file has no edge rows (ne = 1e-30)\n";
		++failures;
	}
	std::cout << "CheckFinite: " << failures << " failures in " << rows.size() << " rows (" << edge_rows << " edge rows)\n";
	return failures;
}

// ---------------------------------------------------------------- Grackle (nH, T) table lookup

constexpr Real grackle_rtol = 1.0e-10;
constexpr Real grackle_derivative_rtol = 1.0e-6;
constexpr int grackle_scan_points = 40;
constexpr const char *expected_grackle_header = "nH,T,Lambda_net,xe_CIE,dLambda_dT,dxe_dT,dxe_dnH";

struct GrackleRow {
	Real nH, T, Lambda, xe, dLambda_dT, dxe_dT, dxe_dnH;
};

static auto ReadGrackleCSV(const std::string &path) -> std::vector<GrackleRow>
{
	std::vector<GrackleRow> rows;
	std::ifstream file(path);
	if (!file) {
		std::cout << "ISMCoolingRates: cannot open reference file '" << path << "'\n";
		return rows;
	}
	std::string line;
	std::getline(file, line);
	if (line != expected_grackle_header) {
		std::cout << "ISMCoolingRates: unexpected header in '" << path << "'\n  got:      " << line << "\n  expected: " << expected_grackle_header
			  << '\n';
		return rows;
	}
	while (std::getline(file, line)) {
		std::stringstream ss(line);
		std::string tok;
		GrackleRow r{};
		for (Real *f : {&r.nH, &r.T, &r.Lambda, &r.xe, &r.dLambda_dT, &r.dxe_dT, &r.dxe_dnH}) {
			std::getline(ss, tok, ',');
			*f = std::stod(tok);
		}
		rows.push_back(r);
	}
	return rows;
}

/// Relative comparison with an absolute floor, for quantities that vanish.
static auto Close(Real got, Real ref, Real rtol, Real floor = 0.) -> bool { return std::abs(got - ref) <= rtol * std::abs(ref) + floor; }

static auto CheckGrackleLookup(const quokka::ISMCooling::GrackleNTGpuConst &table, const std::vector<GrackleRow> &rows) -> int
{
	int failures = 0;
	for (const GrackleRow &r : rows) {
		const auto v = quokka::ISMCooling::LookupGrackleNT(r.nH, r.T, table);
		// the floors are for derivatives that vanish identically, where the centred difference leaves roundoff
		const bool ok = Close(v.Lambda, r.Lambda, grackle_rtol) && Close(v.xe, r.xe, grackle_rtol) &&
				Close(v.dLambda_dT, r.dLambda_dT, grackle_derivative_rtol, 1.0e-8 * std::abs(r.Lambda) / r.T) &&
				Close(v.dxe_dT, r.dxe_dT, grackle_derivative_rtol, 1.0e-8 * std::abs(r.xe) / r.T) &&
				Close(v.dxe_dnH, r.dxe_dnH, grackle_derivative_rtol, 1.0e-8 * std::abs(r.xe) / r.nH);
		if (!ok) {
			if (failures < max_reports) {
				std::cout << "  nH=" << r.nH << " T=" << r.T << ": Lambda " << v.Lambda << " (reference " << r.Lambda << "), xe " << v.xe
					  << " (" << r.xe << "), dLambda_dT " << v.dLambda_dT << " (" << r.dLambda_dT << "), dxe_dT " << v.dxe_dT << " ("
					  << r.dxe_dT << "), dxe_dnH " << v.dxe_dnH << " (" << r.dxe_dnH << ")\n";
			}
			++failures;
		}
	}
	std::cout << "CheckGrackleLookup: " << failures << " of " << rows.size() << " points failed\n";
	return failures;
}

/// Equal up to the roundoff of the log/exp round trip of the clamped inputs
static auto GrackleValuesAreEqual(const quokka::ISMCooling::GrackleNTValues &a, const quokka::ISMCooling::GrackleNTValues &b, bool derivatives = true) -> bool
{
	constexpr Real rtol = 1.0e-9;
	const bool values = Close(a.Lambda, b.Lambda, rtol) && Close(a.xe, b.xe, rtol);
	return values && (!derivatives || (Close(a.dLambda_dT, b.dLambda_dT, rtol) && Close(a.dxe_dT, b.dxe_dT, rtol) && Close(a.dxe_dnH, b.dxe_dnH, rtol)));
}

/// The derivatives with respect to a coordinate that lies outside the table range must vanish.
static auto GrackleDerivativesVanishOutside(const quokka::ISMCooling::GrackleNTValues &v, bool nH_outside, bool T_outside) -> bool
{
	return (!T_outside || (v.dLambda_dT == 0. && v.dxe_dT == 0.)) && (!nH_outside || v.dxe_dnH == 0.);
}

static auto GrackleValuesAreSane(const quokka::ISMCooling::GrackleNTValues &v) -> bool
{
	const bool finite =
	    std::isfinite(v.Lambda) && std::isfinite(v.dLambda_dT) && std::isfinite(v.xe) && std::isfinite(v.dxe_dT) && std::isfinite(v.dxe_dnH);
	const bool clamped_ok = (v.xe > 0.) || (v.dxe_dT == 0. && v.dxe_dnH == 0.); // xe is clamped to >= 0, with zero derivatives where it is
	return finite && v.xe >= 0. && clamped_ok;
}

static auto CheckGrackleClamp(const quokka::ISMCooling::GrackleNTGpuConst &table) -> int
{
	using quokka::ISMCooling::LookupGrackleNT;
	const std::array<Real, 2> lo = {table.table.coord_min[0], table.table.coord_min[1]};
	const std::array<Real, 2> hi = {table.table.coord_max[0], table.table.coord_max[1]};
	const Real nH_lo = std::exp(lo[0]);
	const Real nH_hi = std::exp(hi[0]);
	const Real T_lo = std::exp(lo[1]);
	const Real T_hi = std::exp(hi[1]);
	int failures = 0;
	// outside the table, Lambda and xe equal the lookup at the clamped corner, and the derivatives vanish
	const std::array<std::array<Real, 4>, 4> cases = {{
	    {1.0e-12, 1.0e10, nH_lo, T_hi}, // low density, hot (hot halo gas)
	    {1.0e8, 1.0, nH_hi, T_lo},	    // high density, cold
	    {1.0e-12, 1.0, nH_lo, T_lo},
	    {1.0e8, 1.0e10, nH_hi, T_hi},
	}};
	for (const auto &c : cases) {
		const auto out = LookupGrackleNT(c[0], c[1], table);
		const auto corner = LookupGrackleNT(c[2], c[3], table);
		if (!GrackleValuesAreSane(out) || !GrackleValuesAreEqual(out, corner, false) || !GrackleDerivativesVanishOutside(out, true, true)) {
			std::cout << "  (nH, T) = (" << c[0] << ", " << c[1] << "): Lambda " << out.Lambda << ", dLambda_dT " << out.dLambda_dT << ", xe "
				  << out.xe << " does not equal the corner (" << corner.Lambda << ", " << corner.dLambda_dT << ", " << corner.xe << ")\n";
			++failures;
		}
	}
	// a scan over the table range (and beyond it): all values finite, xe >= 0
	int negative_raw = 0; // points where the clamp is active
	for (int i = 0; i < grackle_scan_points; ++i) {
		for (int j = 0; j < grackle_scan_points; ++j) {
			const Real fx = -0.1 + 1.2 * static_cast<Real>(i) / (grackle_scan_points - 1);
			const Real fy = -0.1 + 1.2 * static_cast<Real>(j) / (grackle_scan_points - 1);
			const Real nH = std::exp(lo[0] + fx * (hi[0] - lo[0]));
			const Real T = std::exp(lo[1] + fy * (hi[1] - lo[1]));
			const auto v = LookupGrackleNT(nH, T, table);
			negative_raw += (v.xe == 0.) ? 1 : 0;
			if (!GrackleValuesAreSane(v) || !GrackleDerivativesVanishOutside(v, fx < 0. || fx > 1., fy < 0. || fy > 1.)) {
				if (failures < max_reports) {
					std::cout << "  scan point (nH, T) = (" << nH << ", " << T
						  << ") is not finite, has xe < 0, or has a nonzero derivative outside the table\n";
				}
				++failures;
			}
		}
	}
	if (negative_raw == 0) {
		std::cout << "CheckGrackleClamp: the scan never reached the xe < 0 region of the table\n";
		++failures;
	}
	std::cout << "CheckGrackleClamp: " << failures << " failures (" << negative_raw << " scan points with xe clamped to 0)\n";
	return failures;
}

static auto CheckGrackleRegistry(const quokka::ISMCooling::GrackleNTGpuConst &table, Real zmet, Real X) -> int
{
	int failures = 0;
	if (quokka::ISMCooling::GetGrackleNTTable() != nullptr) {
		std::cout << "CheckGrackleRegistry: the table is registered before RegisterGrackleNTTable\n";
		++failures;
	}
	quokka::ISMCooling::RegisterGrackleNTTable(table, table);
	const auto *registered = quokka::ISMCooling::GetGrackleNTTable();
	if (registered == nullptr || registered->zmet != zmet || registered->H_mass_fraction != X) {
		std::cout << "CheckGrackleRegistry: the registered table does not match\n";
		++failures;
	} else {
		const auto direct = quokka::ISMCooling::LookupGrackleNT(1.0, 1.0e4, table);
		const auto via_registry = quokka::ISMCooling::LookupGrackleNT(1.0, 1.0e4, *registered);
		failures += GrackleValuesAreEqual(direct, via_registry) ? 0 : 1;
	}
	std::cout << "CheckGrackleRegistry: " << failures << " failures\n";
	return failures;
}

static auto RunGrackleChecks() -> int
{
	amrex::ParmParse const pp_ism("ism_test");
	amrex::ParmParse const pp_cooling("ism_cooling");
	std::string reference_path;
	std::string table_path;
	pp_ism.get("grackle_reference_csv", reference_path);
	pp_cooling.get("grackle_nT_table", table_path);
	const std::vector<GrackleRow> rows = ReadGrackleCSV(reference_path);
	if (rows.empty()) {
		return 1;
	}
	const auto data = quokka::ISMCooling::ReadGrackleNTTable(table_path);
	const auto attrs = quokka::ISMCooling::ReadGrackleNTAttributes(table_path);
	const quokka::ISMCooling::GrackleNTGpuConst table{data->const_tables_host(), attrs.zmet, attrs.H_mass_fraction};
	return CheckGrackleLookup(table, rows) + CheckGrackleClamp(table) + CheckGrackleRegistry(table, attrs.zmet, attrs.H_mass_fraction);
}

auto problem_main() -> int
{
	amrex::ParmParse const pp("ism_test");
	std::string path;
	pp.get("reference_csv", path);
	const std::vector<Row> rows = ReadCSV(path);
	if (rows.empty()) {
		return 1;
	}
	const int failures = CheckAgainstReference(rows) + CheckDerivativesFD(rows) + CheckFinite(rows) + RunGrackleChecks();
	std::cout << (failures == 0 ? "ISMCoolingRates: PASSED\n" : "ISMCoolingRates: FAILED\n");
	return (failures == 0) ? 0 : 1;
}
